-- Generated by content/pipeline/seed_theory.py — do not hand-edit.
-- Seeds lesson rows for the surface_area_volume chapter's theory content.

begin;

insert into lessons (id, concept_id, title, body, hook_kind, hook, try_it, sort_order) values
  ('t_c9_sav_cuboid_cube', 'c9.sav.cuboid_cube', 'Cuboids & Cubes', 'A cuboid is a box shape: two matching ends, four flat sides, every corner a right angle. A cube is just a cuboid where all three sides — length, breadth, height — are equal.', 'real_world', 'Every cardboard box starts as a flat sheet that gets folded up. To know how big that sheet must be, packaging designers add up the areas of the box''s six faces — its total surface area.', 'A shoebox is 30 cm long, 20 cm wide and 15 cm tall. Roughly how much cardboard wraps around it?', 1),
  ('t_c9_sav_cylinder', 'c9.sav.cylinder', 'Right Circular Cylinders', 'A cylinder is two identical circles joined by a curved side, like a tin can. "Curved surface" means just the tube part; "total surface" adds the two circular ends.', 'real_world', 'Fizzy-drink cans are cylinders partly because a round wall spreads the gas pressure evenly. A box-shaped can would bulge at its flat sides and need thicker, heavier metal to stay in shape.', 'A can is 10 cm tall with a 3.5 cm radius. Is more metal used for the curved side or the two circular ends?', 2),
  ('t_c9_sav_cone', 'c9.sav.cone', 'Right Circular Cones', 'A cone comes to a point above a circular base. Its "slant height" is the distance along the sloped surface from the tip to the edge of the base — not the same as the straight-up height through the middle.', 'real_world', 'A cone holds exactly one-third as much as a cylinder with the same base and the same height. That''s why a cone of ice cream holds less than it looks — most of the space is near the wide top.', 'An ice-cream cone stands 12 cm tall with a 2.5 cm radius. Which distance — height or slant height — would you measure to know how much wafer covers the outside?', 3),
  ('t_c9_sav_pyramid', 'c9.sav.pyramid', 'Pyramids', 'A pyramid has a flat base and triangular faces that meet at one point (the apex). Its volume is one-third of the base area times the height — always a third, whatever the base shape.', 'historical', 'An Egyptian scroll from about 1850 BCE, the Moscow Mathematical Papyrus, correctly works out the volume of a pyramid with its top cut off — one of the oldest volume calculations known. The first proof of the one-third rule is credited to the Greek mathematician Eudoxus, about 1,500 years later.', null, 4),
  ('t_c9_sav_sphere_hemisphere', 'c9.sav.sphere_hemisphere', 'Spheres & Hemispheres', 'A sphere is a perfectly round ball; a hemisphere is a solid ball cut exactly in half. A solid hemisphere''s total surface counts the curved half plus the flat circle where it was cut — easy to forget the flat part. An open bowl is different: it has only the curved surface.', 'real_world', 'Soap bubbles are round because the soap film pulls itself as tight as it can, and of all shapes holding the same amount of air, a sphere has the smallest surface area.', 'A glass paperweight is a solid hemisphere with radius 7 cm. If you painted all of it, would you paint the flat circular base as well as the curved top?', 5),
  ('t_c9_sav_scaling', 'c9.sav.scaling', 'Changing Dimensions', 'Double every side of a shape and its surface area does not just double — it becomes four times as much, because area scales by the square of the size change. Volume becomes eight times as much, scaling by the cube.', 'historical', 'In 1638 Galileo pointed out that an animal can''t simply be scaled up. Double its size and its weight (set by volume) grows 8 times, but the strength of its bones (set by their cross-section area) grows only 4 times. That''s why big animals need much thicker bones.', 'A cube''s side is doubled. Its old surface area was 24 cm². What''s the new surface area?', 6),
  ('t_c9_sav_units', 'c9.sav.units', 'Units & Conversions', 'Area is measured in square units (cm²) and volume in cubic units (cm³) — they are never interchangeable. For volume, 1 litre equals exactly 1000 cm³, which is the conversion used to move between everyday measurements and geometry.', 'real_world', 'A 1-litre milk carton holds exactly as much as a hollow cube 10 cm on each side, because 1 litre is defined as 1000 cm³ and 10 × 10 × 10 = 1000.', 'A tank holds 5000 cm³ of water. How many litres is that?', 7)
